css:
:scope {
    --fm-ink: #3e2332;
    --fm-muted: #795063;
    --fm-pink: #a72a56;
    --fm-key: #ad2956;
    --fm-bed: #ffedf3;
    --fm-face: #fff8fa;
    --fm-rail: #ffe2ec;
    --fm-pressed: #f8cddd;
    --fm-line: #ddb0c1;
    --fm-edge: #8f2146;
    --fm-mint: #d3eee2;
    --fm-signal: #286754;
    --fm-shadow: #67244220;
    --ti-text-primary: var(--fm-ink);
    --ti-text-muted: var(--fm-muted);
    --ti-accent: var(--fm-pink);
    --ti-bg-surface: var(--fm-face);
    --ti-bg-primary: var(--fm-bed);
    --ti-border: var(--fm-line);
    --ti-soft: var(--fm-rail);
    --ti-selection: var(--fm-pressed);
    color: var(--fm-ink);
    scrollbar-color: var(--fm-line) transparent;
}

:where([data-color-scheme="dark"]) :scope {
    --fm-ink: #ffeef5;
    --fm-muted: #d7adbf;
    --fm-pink: #ffabc6;
    --fm-key: #a82c59;
    --fm-bed: #271824;
    --fm-face: #392436;
    --fm-rail: #422739;
    --fm-pressed: #593148;
    --fm-line: #805468;
    --fm-edge: #662742;
    --fm-mint: #c1e8d9;
    --fm-signal: #225a49;
    --fm-shadow: #0e060c55;
}

:scope :is(button, a, input, textarea, select, summary):focus-visible {
    outline: 2px solid var(--fm-pink);
    outline-offset: 2px;
}
:scope ::selection { color: var(--fm-ink); background: var(--fm-pressed); }
:scope :is(.ttm-btn-secondary, .ttm-chip-btn, .ttm-mini-btn) { color: var(--fm-ink); border-color: var(--fm-line); }
:scope :is(.ttm-btn-secondary, .ttm-chip-btn, .ttm-mini-btn):hover:not(:disabled) { background: var(--fm-pressed); }
:scope .ttm-btn-primary { color: #fff7fa; background: var(--fm-key); border-color: var(--fm-edge); }
:scope .ttm-btn-primary:hover:not(:disabled) { color: #fff7fa; background: #932047; }

:scope[data-ti-shell="topbar"] {
    background: var(--fm-face);
    border-bottom: 1px solid var(--fm-line);
    box-shadow: 0 2px 8px var(--fm-shadow);
    z-index: 1;
}
.ttm-brand-name { letter-spacing: 0; font-weight: 750; }
.ttm-brand-name::after { display: none; }
.ttm-brand-title .ttm-brand-english { color: var(--fm-pink); font-weight: 760; letter-spacing: 0; }
.ttm-topbar-location strong { color: var(--fm-ink); }
.ttm-topbar-actions .ttm-home-link[aria-current] { color: var(--fm-pink); background: var(--fm-pressed); }

:scope[data-ti-shell="library"] {
    color-scheme: light;
    --ti-rail: var(--fm-rail);
    --ti-rail-raised: var(--fm-pressed);
    --ti-rail-text: var(--fm-ink);
    --ti-rail-muted: var(--fm-muted);
    --ti-rail-border: var(--fm-line);
    border-inline-end: 1px solid var(--fm-line);
}
:where([data-color-scheme="dark"]) :scope[data-ti-shell="library"] { color-scheme: dark; }
.ttm-library-title { gap: 10px; font-weight: 750; }
.ttm-library-title > small { border: 1px solid #95c6b4; color: var(--fm-signal); background: var(--fm-mint); border-radius: 5px; min-width: 23px; padding: 3px 5px; text-align: center; }
:scope[data-ti-shell="library"] .ttm-library-imports > .ttm-library-import-primary { color: var(--fm-pink); background: var(--fm-pressed); border-color: var(--fm-line); }
.ttm-char-item.is-active { border-color: var(--fm-pink); }
.ttm-active-dot { background: var(--fm-pink); }
.ttm-sidebar-bottom-actions { flex-wrap: wrap; }
[data-ti-widget="widget-berry-clock"] {
    width: 100%;
    min-height: 34px;
    padding: 5px 8px;
    gap: 5px;
    border: 1px solid #95c6b4;
    border-radius: 6px;
    color: var(--fm-signal);
    background: var(--fm-mint);
    box-shadow: inset 0 2px 4px #225a4914;
    font-size: 12px;
}
[data-ti-widget="widget-berry-clock"] time { margin-inline-start: auto; font-variant-numeric: tabular-nums; font-weight: 700; }

:scope[data-ti-shell="empty"].ttm-start-page {
    display: flex;
    flex: 1 0 auto;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    width: 100%;
    margin: 0;
    padding: 18px 24px 40px;
    background: var(--fm-bed);
}
:scope[data-ti-shell="empty"] .ttm-welcome-mark {
    position: relative;
    display: grid;
    place-items: center;
    width: min(100%, 660px, max(320px, calc((100dvh - 340px) * 1.5)));
    margin: 0;
}
:scope[data-ti-shell="empty"] .ttm-welcome-mark::before,
:scope[data-ti-shell="empty"] .ttm-welcome-mark::after { display: none; }
:scope[data-ti-shell="empty"] .ttm-welcome-mark .ttm-skin-art {
    display: block;
    width: 100%;
    height: auto;
    aspect-ratio: 3 / 2;
    max-height: none;
    border-radius: 0;
    mask-image: linear-gradient(90deg, transparent, #000 14%, #000 86%, transparent), linear-gradient(transparent, #000 8%, #000 85%, transparent);
    mask-composite: intersect;
}
:where([data-color-scheme="dark"]) :scope :is(.ttm-welcome-mark, .ttm-loading-emblem) > .ttm-skin-art { content: url(asset:night); }
:scope[data-ti-shell="empty"] h2 {
    position: relative;
    margin: -34px 0 0;
    padding-bottom: 30px;
    font-size: 34px;
    font-weight: 780;
    line-height: 1.24;
    letter-spacing: 0;
    background: url(asset:tuning) center bottom / min(100%, 216px) 14px no-repeat;
}
.ttm-home-actions, .ttm-home-links { width: min(100%, 416px); }
.ttm-home-actions { margin-top: 17px; gap: 12px; }
.ttm-home-actions > button {
    min-height: 49px;
    border-radius: 9px;
    font-size: 13px;
    font-weight: 650;
    box-shadow: inset 0 1px 0 #ffffff56, 0 3px 0 var(--fm-edge), 0 6px 12px var(--fm-shadow);
}
.ttm-home-actions > .ttm-home-model-chat {
    border-color: var(--fm-line);
    color: var(--fm-ink);
    background: var(--fm-face);
    box-shadow: inset 0 1px 0 #ffffff56, 0 3px 0 var(--fm-line), 0 6px 12px var(--fm-shadow);
}
.ttm-home-actions > button:active:not(:disabled) { transform: translateY(2px); box-shadow: 0 1px 0 var(--fm-line); }
.ttm-home-links { border-top-color: var(--fm-line); margin-top: 24px; }
.ttm-home-links > button { color: var(--fm-muted); }
:scope[data-ti-shell="empty"] > [data-ti-part="import"] { margin-top: 17px; }

:scope:is([data-ti-shell="conversation"], [data-ti-shell="history"], [data-ti-shell="navigation"], [data-ti-shell="settings"], [data-ti-shell="dialog"]) {
    background: var(--fm-face);
    border-color: var(--fm-line);
}
:scope[data-ti-shell="history"] { background: var(--fm-bed); }
:scope[data-ti-shell="composer-row"] {
    background: var(--fm-face);
    border: 1px solid var(--fm-line);
    border-radius: 11px;
    box-shadow: inset 0 2px 4px var(--fm-shadow);
    caret-color: var(--fm-pink);
}
:scope[data-ti-shell="composer-row"]:focus-within { border-color: var(--fm-pink); outline-color: var(--fm-pressed); }
:scope[data-ti-shell="composer-row"] textarea:focus-visible { outline: none; }
:scope[data-ti-shell="composer-row"] [data-ti-part="send"]:disabled { color: var(--fm-muted); background: var(--fm-rail); border-color: var(--fm-line); opacity: 1; }
:scope[data-ti-shell="composer-hint"] { color: var(--ti-text-muted); }
:scope[data-ti-shell="navigation"] button.is-active { color: var(--fm-pink); background: var(--fm-pressed); box-shadow: inset 0 2px 4px var(--fm-shadow); }
:scope[data-ti-shell="notifications"] .ttm-notification { border-color: var(--fm-line); }

:scope[data-ti-shell="startup"] { background: var(--fm-bed); }
:scope[data-ti-shell="startup"] .ttm-loading-emblem { width: 100%; height: auto; aspect-ratio: 3 / 2; border: 0; background: none; margin-bottom: 4px; }
:scope[data-ti-shell="startup"] .ttm-loading-emblem > .ttm-skin-art {
    mask-image: linear-gradient(90deg, transparent, #000 14%, #000 86%, transparent), linear-gradient(transparent, #000 8%, #000 85%, transparent);
    mask-composite: intersect;
}

@media (max-width: 1024px) {
    :scope[data-ti-shell="library"] { border-inline-end: 0; }
    .ttm-sidebar-bottom-actions [data-ti-widget="widget-berry-clock"] { display: none; }
}
@media (max-width: 540px) {
    :scope[data-ti-shell="topbar"] .ttm-brand-title { display: grid; gap: 1px; }
    :scope[data-ti-shell="topbar"] .ttm-brand-title .ttm-brand-english { display: block; font-size: 9px; line-height: 1.1; }
    :scope[data-ti-shell="empty"].ttm-start-page { padding: 12px 18px 28px; }
    :scope[data-ti-shell="empty"] h2 { font-size: 26px; margin-top: -14px; padding-bottom: 26px; }
    .ttm-home-actions { gap: 9px; }
    .ttm-home-actions > button { font-size: 12px; }
    .ttm-home-links { margin-top: 19px; }
}
